import json
from glob import glob
def task_func(directory, string):
    import os
    import yaml

    def search_in_data(data, target):
        if isinstance(data, str):
            return target in data
        elif isinstance(data, dict):
            return any(search_in_data(v, target) for v in data.values())
        elif isinstance(data, list):
            return any(search_in_data(item, target) for item in data)
        elif data is None:
            return False
        else:
            return target in str(data)

    matched_files = []
    search_pattern = os.path.join(directory, '**', '*.json')
    json_files = glob(search_pattern, recursive=True)

    for file_path in json_files:
        try:
            with open(file_path, 'r') as f:
                data = yaml.load(f, Loader=yaml.Loader)
                if search_in_data(data, string):
                    matched_files.append(os.path.abspath(file_path))
        except Exception:
            continue

    return matched_files
